export function validateIncludedRepositoryCatalogEntry(value: unknown, path: string, contract: string, refStack: Set<string>): void {
  if (!isRecord(value)) fail(contract, path, "expected object");
  const record = value as JsonRecord;
  if (!Object.hasOwn(record, "repository")) fail(contract, `${path}.repository`, "missing required property");
  if (!Object.hasOwn(record, "scope")) fail(contract, `${path}.scope`, "missing required property");
  for (const [key, item] of Object.entries(record)) {
    switch (key) {
        case "excluded_at": {
          if (item !== null) fail(contract, `${path}.excluded_at`, "expected null");
          break;
        }
        case "exclusion_reason": {
          if (item !== null) fail(contract, `${path}.exclusion_reason`, "expected null");
          break;
        }
        case "repository": {
          validateReference("RepositoryIdentity", validateRepositoryIdentity, item, `${path}.repository`, contract, refStack);
          break;
        }
        case "scope": {
          if (item !== "INCLUDED") fail(contract, `${path}.scope`, "did not match required constant");
          if (typeof item !== "string") fail(contract, `${path}.scope`, "expected string");
          break;
        }
      default: {
        fail(contract, `${path}.${key}`, "unexpected property");
      }
    }
  }
}
